import re

from ..connection_cache import ConnectionCache
from ..logger import LOGGER

from ..timer.timer import timestr_to_secs, secs_to_timestr

from ..exception import AuthorizationFailure


class ConnectionInterface(object):

    def __init__(self):
        self.cache = ConnectionCache()
        self._bsc_names = {}

    @property
    def bsc_name(self):
        conn_index = self.cache.current_conn_index
        return self._bsc_names.get(conn_index, '')

    def bsc_connection(self, host='10.42.89.4', alias=None, port=23, timeout=None):
        """
        Open Telnet connection to BSC server. Default server is 10.42.89.4


        **Input parameters:**

        +----------------+------+--------------------------------------+
        | Parameter name | Man. | Description                          |
        +================+======+======================================+
        | host           | No   | host IP address (default 10.42.89.4) |
        +----------------+------+--------------------------------------+
        | alias          | No   | connection alias                     |
        +----------------+------+--------------------------------------+
        | port           | No   | port  (default 22)                   |
        +----------------+------+--------------------------------------+
        | timeout        | No   | connection timeout                   |
        +----------------+------+--------------------------------------+


        **Examples:**

        .. code-block:: robotframework

            BSC Connection
            BSC Connection    host=10.42.89.4
            BSC Connection    host=10.42.89.4  username=SYSTEM  password=SYSTEM


        | **Return value:**
        | a connection index (integer)
        """
        return self.cache.open_connection(host=host, alias=alias, port=port, timeout=timeout)

    def bsc_ssh_connection(self, host='10.42.89.4', alias=None, port=22, timeout=None,
                           username='SYSTEM', password='SYSTEM'):
        """
        Open SSH connection to BSC server. Default server is 10.42.89.4


        **Input parameters:**

        +----------------+------+--------------------------------------+
        | Parameter name | Man. | Description                          |
        +================+======+======================================+
        | host           | No   | host IP address (default 10.42.89.4) |
        +----------------+------+--------------------------------------+
        | alias          | No   | connection alias                     |
        +----------------+------+--------------------------------------+
        | port           | No   | port  (default 22)                   |
        +----------------+------+--------------------------------------+
        | timeout        | No   | connection timeout                   |
        +----------------+------+--------------------------------------+
        | username       | No   | BSC user                             |
        +------------------+------+------------------------------------+
        | password       | No   | BSC password                         |
        +----------------+------+--------------------------------------+


        **Examples:**

        .. code-block:: robotframework

            BSC Connection
            BSC Connection    host=10.42.89.4
            BSC Connection    host=10.42.89.4  username=SYSTEM  password=SYSTEM


        | **Return value:**
        | a connection index (integer)
        """
        res = self.cache.open_ssh_connection(host=host, alias=alias, port=port, timeout=timeout,
                                             usr=username, pwd=password)
        bsc_output = self.cache.current_conn.read_until('<', timeout=2)
        bsc_name = self._get_bsc_name(bsc_output)
        self._register_bsc_name(bsc_name)
        return res

    def bsc_login(self, username='SYSTEM', password='SYSTEM', login_prompt='ENTER USERNAME <',
                  password_prompt='ENTER PASSWORD <', login_timeout='0.5 second',
                  login_incorrect='/*** USER AUTHORIZATION FAILURE ***/'):
        """
        Log in to the Telnet BSC server with the given user credentials.


        **Input parameters:**

        +------------------+------+--------------------------------------------------+
        | Parameter name   | Man. | Description                                      |
        +==================+======+==================================================+
        | username         | No   | BSC user                                         |
        +------------------+------+--------------------------------------------------+
        | password         | No   | BSC password                                     |
        +------------------+------+--------------------------------------------------+
        | login_prompt     | No   | login prompt                                     |
        +------------------+------+--------------------------------------------------+
        | password_prompt  | No   | password prompt                                  |
        +------------------+------+--------------------------------------------------+
        | login_timeout    | No   | timeout for login                                |
        +------------------+------+--------------------------------------------------+
        | login_incorrect  | No   | expected output in case of authorization failure |
        +------------------+------+--------------------------------------------------+


        **Example:**

        .. code-block:: robotframework

            BSC Login


        | **Return value:**
        | login output from BSC
        """
        if login_timeout:
            login_timeout = timestr_to_secs(login_timeout)
        self.cache.current_conn.read_until(login_prompt, timeout=login_timeout)
        self.cache.current_conn.write("{}\r\n".format(username))
        self.cache.current_conn.read_until(password_prompt, timeout=login_timeout)
        self.cache.current_conn.write("{}\r\n".format(password))
        login_output = self.cache.current_conn.read_until('<', timeout=login_timeout)
        LOGGER.debug(login_output)
        if login_incorrect in login_output:
            raise AuthorizationFailure('Invalid credentials')
        else:
            LOGGER.info('Connection with host {} established'.format(self.cache.current_conn.host))
        self.cache.current_conn.read_very_eager()
        bsc_name = self._get_bsc_name(login_output)
        self._register_bsc_name(bsc_name)
        return login_output

    def switch_connection(self, alias_or_index=None):
        """
        Switch between active connections using an index or an alias.


        **Input parameters:**

        +------------------+------+---------------------------+
        | Parameter name   | Man. | Description               |
        +==================+======+===========================+
        | alias_or_index   | No   | connection alias or index |
        +------------------+------+---------------------------+


        | **Return value:**
        | the index of previous active connection. If ``alias_or_index`` is ``None``, return the current connection.


        **Full example:**

        .. code-block:: robotframework

            Bsc Connection
            Bsc Login
            Bsc Connection    alias=2nd conn
            Bsc Login
            Write    SOME COMMAND
            Read Until    EXPECTED OUTPUT    5
            ${old index}=    Switch Connection    1  # switch to connection with index=1
            Write    SOME COMMAND
            Read Unitl    EXPECTED OUTPUT    5
            Switch Connection    2nd conn  # witch to connection with alias=2nd conn
            Write    SOME COMMAND
            Read Until    EXPECTED OUTPUT
            Switch Connection    ${old index}  # switch back to the original connection
        """
        old_index = self.cache.current_conn_index
        self.cache.switch(alias_or_index)
        return old_index

    def set_timeout(self, timeout):
        """
        Set timeout used for waiting for output from Telnet(SSH)Connection.read_until in the current connection.


        .. note::
            The timeout must be given in time string format. The old timeout is returned and can be used
            to restore the timeout later.


        | **Author:** andrzej.cichon@nokia.com
        | **Maintainer:** andrzej.cichon@nokia.com
        | **Released in:** ---


        **Input parameters:**

        +----------------+------+----------------------------------------------------------------------------+
        | Parameter name | Man. | Description                                                                |
        +================+======+============================================================================+
        | timeout        | Yes  | timeout used for waiting for output from Telnet(SSH)Connection.read_until  |
        +----------------+------+----------------------------------------------------------------------------+


        **Examples:**

        .. code-block:: robotframework

            Set Timeout    10
            ${current_timeout}=    Set Timeout    1 minute


        | **Return value:**
        | current timeout as timestring
        """
        old = self.cache.current_conn._read_timeout
        self.cache.current_conn._read_timeout = timestr_to_secs(timeout)
        return secs_to_timestr(old)

    @staticmethod
    def _get_bsc_name(login_output):
        bsc_name_pattern = r'BSC\s+\b(.+)\b\s+\d{4}-'
        bsc_name = re.search(bsc_name_pattern, login_output)
        if bsc_name:
            bsc_name = bsc_name.group(1)
        return bsc_name

    def _register_bsc_name(self, bsc_name):
        conn_index = self.cache.current_conn_index
        self._bsc_names[conn_index] = bsc_name
        if self.bsc_name:
            LOGGER.info('Logged to {}'.format(self.bsc_name))
        else:
            LOGGER.warning("BSC name was not found! There could be a problem with parsing alarms.")

    def close_connection(self):
        """
        Close the current Telnet(SSH) connection.
        It is not an error to close an already closed connection.

        .. note::
            Use ``Close All Connections`` if you want to make sure all open
            connections are closed.

        | **Return value:**
        | remaining output in the connection cache.
        """
        return self.cache.close_current()

    def close_all_connections(self):
        """
        Close all connections and clear connection cache.
        """
        self.cache.close_all()

    def set_encoding(self, encoding=None, errors=None):
        """
        Set the encoding to use for ``Write`` and ``Read Until`` in the current connection.


        **Input parameters:**

        +----------------+------+--------------+
        | Parameter name | Man. | Description  |
        +================+======+==============+
        | encoding       | No   |              |
        +----------------+------+--------------+
        | errors         | No   |              |
        +----------------+------+--------------+


        To ease handling text containing non-ASCII characters, written text is encoded
        and read text decoded by default. The default encoding is UTF-8 that works also with ASCII.
        Encoding can be disabled by using a special encoding value NONE. This is mainly useful
        if you need to get the bytes received from the connection as-is.


        **Examples:**

        .. code-block:: robotframework

             Set Encoding    ISO-8859-15
             Set Encoding    NONE


        It is also possible to configure the error handler to use if encoding or decoding characters fails.
        Accepted values are the same that encode/decode functions in Python strings accept.
        In practice the following values are the most useful:

        - ignore: ignore characters that cannot be encoded (default)
        - strict: fail if characters cannot be encoded
        - replace: replace characters that cannot be encoded with a replacement character


        **Examples:**

        .. code-block:: robotframework

             Set Encoding    errors=ignore
             Set Encoding    ASCII    replace


        | **Return value:**
        | old encoding
        """
        old_encoding = self.cache.current_conn._encoding
        self.cache.current_conn._set_encoding(encoding, errors)
        return old_encoding

    def set_keepalive(self, sleep_time='5 minutes'):
        """
        Turn on keep-alive mechanism for active (current) connection.

        .. note::
            ``sleep_time`` must be given in time string format. It defines how often a keepalive ping is sent.
            The default value of ``sleep_time`` is 5 minutes. It is not recommended to make it lower than that.


        .. note::
            To make this mechanism work, ``Set Keepalive`` must be called explicitly after ``BSC Login``.

        | **Author:** andrzej.cichon@nokia.com
        | **Maintainer:** andrzej.cichon@nokia.com
        | **Released in:** 3.2.0


        **Input parameters:**

        +----------------+------+--------------+
        | Parameter name | Man. | Description  |
        +================+======+==============+
        | sleep_time     | No   |              |
        +----------------+------+--------------+


        **Examples:**

        .. code-block:: robotframework

            Set Keepalive    300 seconds
        """
        sleep_time = timestr_to_secs(sleep_time)
        self.cache.current_conn.upkeeper.sleep_time = sleep_time
        self.cache.current_conn.upkeeper.start()

    def unset_keepalive(self):
        """
        Turn off keep-alive mechanism for active (current) connection.
        """
        self.cache.current_conn.upkeeper.stop()
